# Deriziotis--Michler (1987), 3D4.0/11/13; Lübeck, uni2D4.1.
function fixture_triality(q)
  h=1//2
  rows = [
        fill(1,7),
        [q * (q^4 - q^2 + 1), -q^3 + q, q, q^2 + q, -q^2 + q, q, 0],
        [h * q^3 * (q + 1)^2 * (q^4 - q^2 + 1),
         h * q^3 * (-q^3 + 2*q + 1), h * q^3 * (q + 1), 0, q^3, 0, 0],
        [h * q^3 * (q^3 + 1)^2,
         h * q^3 * (q^3 + 1), h * q^3 * (q + 1), q^3, 0, 0, 0],
        [h * q^3 * (q^3 - 1)^2,
         h * q^3 * (-q^3 + 1), h * q^3 * (-q + 1), 0, q^3, 0, 0],
        [h * q^3 * (q - 1)^2 * (q^4 - q^2 + 1),
         h * q^3 * (q^3 - 2*q + 1), h * q^3 * (-q + 1), q^3, 0, 0, 0],
        [q^7 * (q^4 - q^2 + 1), q^7, 0, 0, 0, 0, 0],
        [q^12, 0, 0, 0, 0, 0, 0],
    ]
  factor = q^8 + q^4 + 1
  sizes = [
        1, (q^2 - 1) * factor, q^2 * (q^6 - 1) * factor,
        h * q^4 * factor * (q^2 - 1)^2 * (q^2 - q + 1),
        h * q^4 * factor * (q^2 - 1)^2 * (q^2 + q + 1),
        q^6 * (q^2 - 1) * (q^6 - 1) * factor,
        q^8 * (q^2 - 1) * (q^6 - 1) * factor,
    ]
  (values=toM(rows),sizes=sizes)
end
function fixture_2D4(q)
  h=1//2
  rows = [
        [q^12, 0, 0, 0, 0, 0, 0, 0, 0],
        [q^7 * (q^4 + 1), q^7, 0, 0, 0, 0, 0, 0, 0],
        [q^6 * (q^4 + q^2 + 1), q^6, q^6, 0, 0, 0, 0, 0, 0],
        [h * q^3 * (q^2 + q + 1) * (q^4 + 1),
         h * q^3 * (q + 1) * (q^2 + 1), h * q^3 * (q^2 + 1),
         h * q^3 * (q + 1), 0, q^3, 0, 0, 0],
        [h * q^3 * (q^2 - q + 1) * (q^4 + 1),
         -h * q^3 * (q - 1) * (q^2 + 1), h * q^3 * (q^2 + 1),
         -h * q^3 * (q - 1), q^3, 0, 0, 0, 0],
        [h * q^3 * (q^2 + q + 1) * (q^4 + 1),
         -h * q^3 * (q^3 - q^2 - q - 1), h * q^3 * (q + 1)^2,
         h * q^3 * (q + 1), q^3, 0, 0, 0, 0],
        [h * q^3 * (q^2 - q + 1) * (q^4 + 1),
         h * q^3 * (q^3 + q^2 - q + 1), h * q^3 * (q - 1)^2,
         -h * q^3 * (q - 1), 0, q^3, 0, 0, 0],
        [q^2 * (q^4 + q^2 + 1), q^2 * (q^2 + 1), q^2 * (q^2 + 1),
         q^2, q^2, q^2, q^2, 0, 0],
        [q * (q^4 + 1), q, q * (q^2 + 1), q, q * (q + 1), -q * (q - 1), q, q, 0],
        fill(1,9),
    ]
  sizes = [
        1, q^10 + q^6 - q^4 - 1, q^12 + q^8 - q^6 - q^2,
        q^16 - q^10 - q^8 + q^2,
        h * (q^18 - q^12 - q^10 + q^4),
        h * (q^18 - q^12 - q^10 + q^4),
        q^20 - q^14 - q^12 + q^6,
        q^22 - q^20 - q^16 + q^12 + q^8 - q^6,
        q^24 - q^22 - q^18 + q^14 + q^10 - q^8,
    ]
  (values=toM(rows),sizes=sizes)
end
